   m=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));var texture=source.HasProperty("_BaseMap")?source.GetTexture("_BaseMap"):source.HasProperty("_MainTex")?source.GetTexture("_MainTex"):null;m.SetTexture("_BaseMap",texture);m.SetColor("_BaseColor",Color.white);
   bool additive=source.name.Contains("ADD")||source.shader.name.Contains("Additive");m.SetFloat("_Surface",1);m.SetFloat("_Blend",additive?2:0);m.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);m.SetFloat("_DstBlend",(float)(additive?BlendMode.One:BlendMode.OneMinusSrcAlpha));m.SetFloat("_ZWrite",0);m.SetFloat("_Cull",0);m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");m.renderQueue=3000;AssetDatabase.CreateAsset(m,path);return m;
