   var fireball=Effect("Combat/Explosions/FireballRoundExplosion/ExplosionFireballFire.prefab");foreach(Transform child in fireball.transform.Cast<Transform>().ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);fireball.name="Brief blast fireball";fireball.transform.SetParent(blast.transform,false);var flame=fireball.GetComponent<ParticleSystem>();Burst(flame,1,3.6f,.34f,new Color(1.5f,.85f,.32f,.9f));var flameRenderer=flame.GetComponent<ParticleSystemRenderer>();flameRenderer.sharedMaterial=Convert(AssetDatabase.LoadAssetAtPath<Material>("Assets/Epic Toon FX/Materials/Misc/Explosions/explosion_sharp_flat_3x3_AB.mat"));var sheet=flame.textureSheetAnimation;sheet.enabled=true;sheet.mode=ParticleSystemAnimationMode.Grid;sheet.numTilesX=3;sheet.numTilesY=3;sheet.animation=ParticleSystemAnimationType.WholeSheet;sheet.frameOverTime=new ParticleSystem.MinMaxCurve(1,AnimationCurve.Linear(0,0,1,1));sheet.startFrame=0;sheet.cycleCount=1;var flameSize=flame.sizeOverLifetime;flameSize.size=new ParticleSystem.MinMaxCurve(1,AnimationCurve.Linear(0,.65f,1,1));
