   var gun=UnityEngine.Object.Instantiate(pack.launcherWeapon);foreach(var p in gun.GetComponentsInChildren<ParticleSystem>(true).ToArray())if(p)UnityEngine.Object.DestroyImmediate(p.gameObject);
