   foreach(var p in flash.GetComponentsInChildren<ParticleSystem>(true))Burst(p,1,p.name=="Glow"?.7f:.9f,p.name=="Glow"?.075f:.11f,new Color(2.2f,1.1f,.18f,p.name=="Glow"?.5f:1));
   PrefabUtility.SaveAsPrefabAsset(gun,AssetDatabase.GetAssetPath(pack.launcherWeapon));UnityEngine.Object.DestroyImmediate(gun);
   var round=new GameObject("Direct-fire cannon round");var model=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TopDownEngine/Demos/Tanks/Prefabs/TankCannonBullet.prefab"),round.transform);VisualUpgrade.Strip(model,false);model.transform.SetLocalPositionAndRotation(Vector3.zero,Quaternion.identity);model.transform.localScale=Vector3.one;
   var renderers=model.GetComponentsInChildren<MeshRenderer>();if(renderers.Length==0)throw new Exception("Tank cannon mesh missing");var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);model.transform.localScale=new Vector3(.25f/bounds.size.x,.25f/bounds.size.y,.52f/bounds.size.z);bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);model.transform.position-=bounds.center;
   string shellPath=Folder+"Shell.mat";var shell=AssetDatabase.LoadAssetAtPath<Material>(shellPath);if(!shell){shell=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(shell,shellPath);}shell.SetColor("_BaseColor",new Color(.9f,.48f,.12f));shell.SetFloat("_Metallic",.4f);shell.SetFloat("_Smoothness",.3f);foreach(var r in renderers){r.sharedMaterial=shell;r.shadowCastingMode=ShadowCastingMode.Off;}
